link.script:
/* ---------------------------------------------------------------------------
   HubSpot video cookie-consent gate + accessible transcript toggle
   (Reuters AODA — permanent fixture)

   Inlined EARLY in 
 (before the standard_header_includes tag) so it strips
   HubSpot video widgets BEFORE HubSpot's own video loader processes them.

   What it does:
   - Defers every HubSpot-hosted video (
) until the visitor has accepted FUNCTIONALITY
     cookies (HubSpot consent category 3). Until then the player iframe is never
     given its src, so no player and no per-video tracking loads.
   - Shows an accessible placeholder with a "Cookie settings" button that
     reopens the HubSpot consent banner.
   - On consent it restores the widget and re-inserts it, so HubSpot's own
     MutationObserver renders the player normally.
   - Wires accessible disclosure toggles for video transcripts
     (.ra-video-transcript, rendered by the shared `video` macro).

   No-op on pages without HubSpot video or transcripts.
   --------------------------------------------------------------------------- */
(function () {
  'use strict';

  var CONSENT_CATEGORY = '3'; // HubSpot "functionality" cookies
  var TEXT = {
    notice: 'This video is hosted by a third party and needs functionality cookies to play.',
    button: 'Cookie settings',
    show: 'Show video transcript',
    hide: 'Hide video transcript'
  };

  /* ---- consent ---------------------------------------------------------- */

  function hasFunctionalConsent() {
    var raw = document.cookie.split('; ').filter(function (r) {
      return r.indexOf('__hs_cookie_cat_pref=') === 0;
    })[0];
    if (!raw) return false;
    var val;
    try { val = decodeURIComponent(raw.split('=')[1]); } catch (e) { val = raw.split('=')[1]; }
    return val.split('_').some(function (c) {
      var p = c.split(':');
      return p[0] === CONSENT_CATEGORY && p[1] === 'true';
    });
  }

  function openCookieSettings(e) {
    if (e) e.preventDefault();
    // Reset the stored choice so the banner reappears and offers a fresh decision.
    document.cookie = '__hs_cookie_cat_pref=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/';
    if (window._hsp && typeof window._hsp.push === 'function') {
      window._hsp.push(['showBanner']);
    }
  }

  /* ---- video gate ------------------------------------------------------- */

  var gated = [];      // HubSpot widgets we've deferred
  var vimeoGated = []; // Vimeo iframes we've deferred

  function buildPlaceholder() {
    var ph = document.createElement('div');
    ph.className = 'ra-video-consent';
    ph.setAttribute('role', 'group');
    ph.setAttribute('aria-label', 'Video requires cookie consent');

    var notice = document.createElement('p');
    notice.className = 'ra-video-consent__text';
    notice.textContent = TEXT.notice;

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'ra-video-consent__btn';
    btn.textContent = TEXT.button;
    btn.addEventListener('click', openCookieSettings);

    ph.appendChild(notice);
    ph.appendChild(btn);
    return ph;
  }

  function gate(widget) {
    if (widget.getAttribute('data-hsv-embed-id-deferred')) return; // already gated
    var id = widget.getAttribute('data-hsv-embed-id');
    if (!id) return;
    // Removing the trigger attribute makes HubSpot's loader selector
    // (div.hs-video-widget[data-hsv-embed-id]:not([data-hsv-status])) skip it.
    widget.setAttribute('data-hsv-embed-id-deferred', id);
    widget.removeAttribute('data-hsv-embed-id');
    widget.classList.add('ra-video--gated');
    if (!widget.querySelector('.ra-video-consent')) {
      widget.appendChild(buildPlaceholder());
    }
    if (gated.indexOf(widget) === -1) gated.push(widget);
  }

  function restore(widget) {
    var id = widget.getAttribute('data-hsv-embed-id-deferred');
    if (!id) return;
    var ph = widget.querySelector('.ra-video-consent');
    if (ph && ph.parentNode) ph.parentNode.removeChild(ph);
    widget.classList.remove('ra-video--gated');
    widget.removeAttribute('data-hsv-embed-id-deferred');
    // Re-insert a fresh node carrying the embed id; HubSpot's persistent
    // MutationObserver picks up the added node and renders the player.
    var fresh = widget.cloneNode(true);
    fresh.setAttribute('data-hsv-embed-id', id);
    fresh.removeAttribute('data-hsv-status');
    if (widget.parentNode) widget.parentNode.replaceChild(fresh, widget);
  }

  // ---- Vimeo (third-party iframe) -------------------------------------
  // Migrated embeds ship the player URL in data-ra-vimeo-src (no src) so the
  // iframe never loads until consent. Legacy raw embeds with a live src are
  // also caught defensively — the src is moved to data-ra-vimeo-src (which
  // cancels the in-flight load) so they gate too.
  function gateVimeo(frame) {
    if (frame.getAttribute('data-ra-gated')) return;
    var src = frame.getAttribute('data-ra-vimeo-src');
    if (!src && frame.src && /player\.vimeo\.com/.test(frame.src)) {
      src = frame.src;
      frame.setAttribute('data-ra-vimeo-src', src);
      frame.removeAttribute('src');
    }
    if (!src) return;
    frame.setAttribute('data-ra-gated', '1');
    frame.style.display = 'none';
    var wrap = (frame.closest && frame.closest('.ra-vimeo-embed')) || frame.parentNode;
    if (wrap) {
      wrap.classList.add('ra-vimeo--gated');
      if (!wrap.querySelector('.ra-video-consent')) wrap.appendChild(buildPlaceholder());
    }
    if (vimeoGated.indexOf(frame) === -1) vimeoGated.push(frame);
  }

  function restoreVimeo(frame) {
    var wrap = (frame.closest && frame.closest('.ra-vimeo-embed')) || frame.parentNode;
    if (wrap) {
      var ph = wrap.querySelector('.ra-video-consent');
      if (ph && ph.parentNode) ph.parentNode.removeChild(ph);
      wrap.classList.remove('ra-vimeo--gated');
    }
    activateVimeo(frame);
  }

  // With consent present we OWN the Vimeo src (HubSpot has no loader for these).
  // Build a BRAND-NEW iframe and set its src via the .src PROPERTY — neither
  // setAttribute('src') on the parsed src-less iframe nor a cloneNode+setAttribute
  // reliably navigates it (the load is dropped and the frame stays blank); a
  // freshly-created element with a property-assigned src loads correctly.
  // Legacy frames already carrying a live src are left as-is.
  var COPY_ATTRS = ['frameborder', 'allow', 'allowfullscreen', 'title', 'class', 'style', 'width', 'height', 'referrerpolicy', 'sandbox'];
  function activateVimeo(frame) {
    if (frame.getAttribute('data-ra-gated') === 'done') return;
    var src = frame.getAttribute('data-ra-vimeo-src');
    if (!src) { frame.setAttribute('data-ra-gated', 'done'); return; }
    var fresh = document.createElement('iframe');
    for (var i = 0; i < COPY_ATTRS.length; i++) {
      if (frame.hasAttribute(COPY_ATTRS[i])) fresh.setAttribute(COPY_ATTRS[i], frame.getAttribute(COPY_ATTRS[i]));
    }
    fresh.setAttribute('data-ra-gated', 'done');
    fresh.style.display = '';
    if (frame.parentNode) frame.parentNode.replaceChild(fresh, frame);
    fresh.src = src;
  }

  function scanAndGate() {
    var consent = hasFunctionalConsent();
    if (!consent) {
      var list = document.querySelectorAll('.hs-video-widget[data-hsv-embed-id]');
      for (var i = 0; i < list.length; i++) gate(list[i]);
    }
    var frames = document.querySelectorAll('iframe[data-ra-vimeo-src], iframe[src*="player.vimeo.com"]');
    for (var j = 0; j < frames.length; j++) {
      if (consent) activateVimeo(frames[j]); else gateVimeo(frames[j]);
    }
  }

  // Catch widgets as they are parsed/injected, before HubSpot's loader scans.
  var observer = null;
  if (typeof MutationObserver === 'function') {
    observer = new MutationObserver(scanAndGate);
    try { observer.observe(document, { childList: true, subtree: true }); } catch (e) { observer = null; }
  }
  if (document.readyState !== 'loading') scanAndGate();
  document.addEventListener('DOMContentLoaded', scanAndGate);

  // Once consent is granted (banner accepted later), load every deferred video.
  var poll = setInterval(function () {
    if (!hasFunctionalConsent()) return;
    clearInterval(poll);
    if (observer) { observer.disconnect(); observer = null; }
    gated.slice().forEach(restore);
    gated.length = 0;
    vimeoGated.slice().forEach(restoreVimeo);
    vimeoGated.length = 0;
  }, 1000);

  /* ---- transcript disclosure ------------------------------------------- */

  var transcriptSeq = 0;

  function wireTranscripts() {
    var toggles = document.querySelectorAll('.ra-video-transcript__toggle');
    for (var i = 0; i < toggles.length; i++) {
      (function (btn) {
        if (btn.getAttribute('data-ra-wired')) return;
        btn.setAttribute('data-ra-wired', '1');

        var panel = document.getElementById(btn.getAttribute('aria-controls') || '');
        if (!panel) {
          panel = btn.parentNode && btn.parentNode.querySelector('.ra-video-transcript__panel');
        }
        if (!panel) return;
        if (!panel.id) {
          panel.id = 'ra-transcript-' + (++transcriptSeq);
        }
        btn.setAttribute('aria-controls', panel.id);
        if (!btn.hasAttribute('aria-expanded')) btn.setAttribute('aria-expanded', 'false');
        panel.hidden = btn.getAttribute('aria-expanded') !== 'true';

        var label = btn.querySelector('.ra-video-transcript__label') || btn;

        btn.addEventListener('click', function () {
          var expanded = btn.getAttribute('aria-expanded') === 'true';
          btn.setAttribute('aria-expanded', String(!expanded));
          panel.hidden = expanded;
          label.textContent = expanded ? TEXT.show : TEXT.hide;
        });
      })(toggles[i]);
    }
  }

  if (document.readyState !== 'loading') wireTranscripts();
  document.addEventListener('DOMContentLoaded', wireTranscripts);
})();

body.script:
var w = getViewport();

function getViewport() {
  var viewPortWidth;

  if (typeof window.innerWidth != 'undefined') {
    viewPortWidth = window.innerWidth;
  } else if (typeof document.documentElement != 'undefined' && typeof document.documentElement.clientWidth != 'undefined' && document.documentElement.clientWidth != 0) {
    viewPortWidth = document.documentElement.clientWidth;
  } else {
    viewPortWidth = document.getElementsByTagName('body')[0].clientWidth;
  }
  return viewPortWidth;
}

$(document).on('click', '.navbar-nav > .dropdown', function(e) {
  if (w > 1200) {
    e.stopPropagation();
  }
});

$(document).on('click', '.navbar-nav > .dropdown a.nav-link, .navbar-nav > .dropdown a.dropdown-item', function(e) {
  if (w > 1200) {
    if ($(this).attr('target') == '_blank') {
      window.open($(this).attr("href"), '_blank');
    } else {
      window.location = $(this).attr("href");
    }
  }
});

var $navbarCollapse = $('.navbar-main .collapse');
// Collapse navigation
$navbarCollapse.on('hide.bs.collapse', function() {
  var $this = $(this);
  $this.addClass('collapsing-out');
});

$navbarCollapse.on('hidden.bs.collapse', function() {
  var $this = $(this);
  $this.removeClass('collapsing-out');
});

$('.navbar-main .dropdown').on('hide.bs.dropdown', function() {
  var $this = $(this).find('.dropdown-menu');
  $this.addClass('close');
  setTimeout(function() {
    $this.removeClass('close');
  }, 200);
});

$('.nav-link').not(".nav-link-d").on('click', function() {
  $('.navbar-collapse').collapse('hide');
});

// Close top bar button
$('.close-top-bar i').click(function() {
  $('.top-bar-text').css("display", "none");
  var navbarHeight = $('#navbar-main').outerHeight();
  $('body').attr('style', 'margin-top:' + navbarHeight + 'px');
});


$(document).ready(function() {

  window.addEventListener("resize", function() {
    var navbarHeight = document.querySelector("#navbar-main").clientHeight;
    document.querySelector("body").style.marginTop = navbarHeight + "px";
  });
  window.dispatchEvent(new Event("resize"));

  if ($('.headroom')[0]) {
    var headroom = new Headroom(document.querySelector("#navbar-main"), {
      offset: 0,
      tolerance: {
        up: 1,
        down: 0
      },
    });
    headroom.init();
  }
});


(function() {
  let trapElement = null;
  let focusableElements = [];
  let firstFocusable = null;
  let lastFocusable = null;

  function getFocusableElements(container) {
    return container.querySelectorAll(
      'a[href], area[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), button:not([disabled]), iframe, object, embed, [tabindex]:not([tabindex="-1"]), [contenteditable]'
    );
  }

  function trapFocusIn(element) {
    trapElement = element;
    focusableElements = Array.from(getFocusableElements(trapElement)).filter(el => el.offsetParent !== null);

    if (focusableElements.length) {
      firstFocusable = focusableElements[0];
      lastFocusable = focusableElements[focusableElements.length - 1];
      firstFocusable.focus();
    }

    document.addEventListener('keydown', handleTrapKeydown);
  }

  function releaseFocusTrap() {
    document.removeEventListener('keydown', handleTrapKeydown);
    trapElement = null;
    focusableElements = [];
    firstFocusable = null;
    lastFocusable = null;
  }

  function handleTrapKeydown(e) {
    if (!trapElement) return;

    if (e.key === 'Tab') {
      const active = document.activeElement;
      const isFirst = active === firstFocusable;
      const isLast = active === lastFocusable;

      if (e.shiftKey) {
        if (isFirst) {
          e.preventDefault();
          lastFocusable.focus();
        }
      } else {
        if (isLast) {
          e.preventDefault();
          firstFocusable.focus();
        }
      }
    }

    // Optional: Allow ESC to close the mobile nav
    if (e.key === 'Escape') {
      $('.navbar-collapse').collapse('hide');
    }
  }

  $(document).on('shown.bs.collapse', '.navbar-collapse', function () {
    trapFocusIn(this);
  });

  $(document).on('hidden.bs.collapse', '.navbar-collapse', function () {
    releaseFocusTrap();
    $('.navbar-toggler').focus();
  });

})();

