link.script:
	document.addEventListener('focusin', function(event) {
	  // Check if focus has moved into a Slick slider (or any element inside it)
	  const focusedSlider = event.target.closest('.slick-slider');

	  if (focusedSlider) {
			console.log("focussed in")
	    // Loop over all Slick sliders on the page
	    $('.slick-slider.slick-initialized').each(function() {
	      // Pause each one (whether it's the focused one or not)
	      $(this).slick('slickPause');
//				$(this).slick('slickSetOption', 'autoplay', false, true);
	    });
	  }
	});

  document.addEventListener("DOMContentLoaded", function () {

		function clearHubSpotCookieConsent() {
		  // HubSpot cookie names can vary, but these are typical ones to clear consent state
			const cookiesToClear = [
        '__hs_cookie_cat_pref',
        '__hs_opt_out',
        '__hs_do_not_track',
        'hubspotutk'
      ];

      cookiesToClear.forEach(name => {
        document.cookie = `${name}=; path=/; domain=${location.hostname}; expires=Thu, 01 Jan 1970 00:00:00 GMT`;
        document.cookie = `${name}=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT`; // fallback without domain
      });
		}

    // Poll for the banner's "Cookies settings" button and click it, so the
    // footer link opens the detailed preferences modal (#hs-modal) directly
    // rather than leaving the user on the Accept/Decline banner.
    function openCookieSettings(attempts = 0) {
      const btn = document.getElementById('hs-eu-cookie-settings-button');
      if (btn) {
        btn.click();
      } else if (attempts < 25) {
        setTimeout(() => openCookieSettings(attempts + 1), 150);
      }
    }

    // Match the "Cookie Settings" link by its href, not by a menu-wrapper class.
    // The footer link lives in `.menu-wrapper` (not `.hs-menu-wrapper`), and the
    // href may be relative (#modify-cookie-settings) or absolute
    // (https://…/#modify-cookie-settings), so match on the hash suffix.
    const cookieLinks = document.querySelectorAll('a[href$="#modify-cookie-settings"]');
    cookieLinks.forEach(link => {
      link.addEventListener("click", function (e) {
        e.preventDefault();
        // AODA 1217165 (2.4.3): remember the control that opened the cookie UI so focus can
        // return to it when the dialog closes.
        window.__raCookieReturnFocus = this;
        // Open HubSpot cookie settings modal
        clearHubSpotCookieConsent();
        if (window._hsp) {
          console.log("Cookie showBanner modal called");
          window._hsp.push(['showBanner']);
          // Re-apply the accessibility treatment (inert background + focus
          // trap) to the re-shown banner — waitForCookieModal only runs on
          // the initial page load, so a re-opened banner would otherwise miss it.
          if (typeof waitForCookieModal === 'function') waitForCookieModal();
          // Then open the detailed cookie-preferences modal directly.
          openCookieSettings();
          // AODA 1217165 (2.4.3): move focus INTO the dialog. Retries because the banner's
          // buttons load async, so the first attempt can find no focusable target.
          if (typeof focusCookieDialog === 'function') focusCookieDialog();
        } else {
          console.warn("Cookie banner not found.");
        }
      });
    });
  });

  // AODA 1217165 (2.4.3): move keyboard focus into the open cookie dialog. Picks the topmost
  // cookie surface (the detailed #hs-modal if visible, else the #hs-eu-cookie-confirmation banner)
  // and focuses its first interactive element. Retries because the buttons/links load async.
  function focusCookieDialog(attempts) {
    attempts = attempts || 0;
    var modal = document.getElementById('hs-modal');
    var banner = document.getElementById('hs-eu-cookie-confirmation');
    var dialog = (modal && modal.offsetParent !== null) ? modal : banner;
    var target = null;
    if (dialog) {
      var focusables = dialog.querySelectorAll(
        'a[href], button:not([disabled]), input:not([disabled]), select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      target = focusables[0] || null;
    }
    if (target) {
      target.focus();
      // If focus didn't take (element not yet focusable), retry.
      if (document.activeElement !== target && attempts < 20) {
        setTimeout(function () { focusCookieDialog(attempts + 1); }, 150);
      }
    } else if (attempts < 20) {
      setTimeout(function () { focusCookieDialog(attempts + 1); }, 150);
    }
  }

  // AODA 1217165/1217166 (2.4.3): return focus to the trigger, but ONLY once the whole cookie UI is
  // dismissed — closing the detailed modal via its "X" can drop back to the banner, and while a
  // surface is still visible focus must stay in it. Deferred callers run this after HubSpot's own
  // close/focus handling (which otherwise leaves focus on the banner container).
  function cookieSurfaceVisible(el) {
    if (!el || el.offsetParent === null) return false;
    var s = getComputedStyle(el);
    return s.opacity !== '0' && s.visibility !== 'hidden' && s.display !== 'none';
  }
  function anyCookieSurfaceVisible() {
    return cookieSurfaceVisible(document.getElementById('hs-modal')) ||
           cookieSurfaceVisible(document.getElementById('hs-eu-cookie-confirmation'));
  }
  // Debounced: banner↔modal transitions (e.g. opening the detailed modal hides the banner for a
  // moment) briefly leave BOTH surfaces invisible, which must NOT be read as "dismissed". Wait for
  // the UI to SETTLE as gone, then focus the trigger and hold it against HubSpot's own focus moves.
  function returnCookieFocus() {
    clearTimeout(window.__raCookieFocusTimer);
    window.__raCookieFocusTimer = setTimeout(function () {
      if (anyCookieSurfaceVisible()) return; // reopened / still transitioning
      // The cookie UI is gone — but closing via "X" doesn't always fire the banner's dismissal
      // observer, so the background can still be `inert` (which makes the trigger unfocusable) and
      // the focus-trap sentinels can linger. Clear both before returning focus.
      restoreBackground();
      var sentinels = document.querySelectorAll('#focus-start, #focus-end');
      for (var i = 0; i < sentinels.length; i++) sentinels[i].remove();
      var trigger = window.__raCookieReturnFocus;
      if (!trigger || !document.contains(trigger) || trigger.offsetParent === null) {
        window.__raCookieReturnFocus = null;
        return;
      }
      trigger.focus();
      var tries = 0;
      var hold = setInterval(function () {
        if (anyCookieSurfaceVisible()) { clearInterval(hold); return; } // reopened — leave it
        if (document.activeElement === trigger || tries++ > 8) {
          clearInterval(hold);
          window.__raCookieReturnFocus = null;
          return;
        }
        trigger.focus(); // HubSpot stole focus (onto the hidden banner) — take it back
      }, 100);
    }, 350);
  }

  function restoreBackground() {
    // Undo the inert state once the banner is gone so content isn't left hidden.
    // NB: this also fires when the banner hides to OPEN the detailed modal, so it must NOT drive
    // focus-return — that is triggered only by a genuine close control (see the click handler).
    document.querySelectorAll('[data-cookie-inert]').forEach(el => {
      el.removeAttribute('inert');
      el.removeAttribute('data-cookie-inert');
    });
  }

  function watchForDismissal(modal) {
    const isVisible = () =>
      document.body.contains(modal) &&
      getComputedStyle(modal).display !== 'none' &&
      getComputedStyle(modal).visibility !== 'hidden';
    const obs = new MutationObserver(() => {
      if (!isVisible()) { restoreBackground(); obs.disconnect(); }
    });
    obs.observe(document.body, {
      childList: true, subtree: true,
      attributes: true, attributeFilter: ['style', 'class', 'hidden']
    });
  }

  function waitForCookieModal(attempts = 0) {
    const modal = document.getElementById("hs-eu-cookie-confirmation");

    if (modal) {
      console.log("✅ Cookie modal found!");

      // 1. Add accessible name
      modal.setAttribute("aria-label", "Cookie preferences dialog");

      // 2. Make background inert (removes it from focus order AND the
      //    accessibility tree) instead of aria-hidden, so focusable content
      //    isn't hidden-but-focusable (WCAG 4.1.2 / axe aria-hidden-focus).
      //    HubSpot wraps the banner in a body-level container (#hs-banner-parent),
      //    so skip the banner's OWN top-level wrapper — computed dynamically —
      //    not just the banner id, otherwise the wrapper (and the banner's
      //    Accept/Decline buttons inside it) become inert and unclickable.
      const modalTop = modal.closest('body > *') || modal;
      document.querySelectorAll('body > *').forEach(el => {
        if (el === modalTop) return;
        if (el.id === 'focus-start' || el.id === 'focus-end') return;
        if (el.tagName === 'SCRIPT' || el.tagName === 'STYLE') return;
        el.setAttribute('inert', '');
        el.setAttribute('data-cookie-inert', '');
      });

      // 3. Add focus trap sentinels
      addFocusSentinels(modal);

      // 4. Restore the background (clear inert) once the banner is dismissed
      watchForDismissal(modal);

    } else if (attempts < 20) {
      setTimeout(() => waitForCookieModal(attempts + 1), 250);
    } else {
      console.warn("⚠️ Cookie modal dismissed.");
    }
  }

  function addFocusSentinels(modal) {
    // Drop any sentinels from a previous showing so re-opening the banner
    // (via the footer "Cookie Settings" link) doesn't accumulate duplicates.
    document.querySelectorAll('#focus-start, #focus-end').forEach(s => s.remove());
    const focusableSelectors = 'a[href], button:not([disabled]), textarea, input, select, [tabindex]:not([tabindex="-1"])';
    const focusableEls = modal.querySelectorAll(focusableSelectors);
    if (focusableEls.length === 0) return;

    const firstEl = focusableEls[0];
    const lastEl = focusableEls[focusableEls.length - 1];

    // Create invisible sentinels
    const startTrap = document.createElement('div');
    startTrap.tabIndex = 0;
    startTrap.id = 'focus-start';
    startTrap.style.cssText = 'position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;';
    startTrap.addEventListener('focus', () => lastEl.focus());

    const endTrap = document.createElement('div');
    endTrap.tabIndex = 0;
    endTrap.id = 'focus-end';
    endTrap.style.cssText = 'position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;';
    endTrap.addEventListener('focus', () => firstEl.focus());

    // Insert before and after modal
    modal.parentNode.insertBefore(startTrap, modal);
    modal.parentNode.insertBefore(endTrap, modal.nextSibling);

    // Focus first focusable element
    firstEl.focus();
  }

  // AODA 1217162 (1.3.1): the detailed cookie-preferences modal (#hs-modal) shows visual headings —
  // "About Cookies" (a ) and the category labels ("Necessary", "Analytics", … which are
  // expand buttons) — with no heading semantics, so heading navigation skipped them. Mark them up.
  // The modal is HubSpot-injected on demand, so treat it whenever it appears. Idempotent (guarded),
  // so the observer can call it repeatedly without duplicating work.
  function markCookiePrefsHeadings() {
    var title = document.querySelector('#hs-modal-introduction > span, #hs-modal-header span, #hs-modal-introduction span');
    if (title && title.getAttribute('role') !== 'heading') {
      title.setAttribute('role', 'heading');
      title.setAttribute('aria-level', '2');
    }
    // ARIA accordion pattern: wrap each expand button in an 
. display:contents keeps the
    // existing flex layout untouched (the button stays the visual/flex element).
    var labels = document.querySelectorAll('.hs-category-label');
    for (var i = 0; i < labels.length; i++) {
      var btn = labels[i];
      if (btn.getAttribute('data-ra-heading') === '1') continue;
      if (btn.closest('h1,h2,h3,h4,h5,h6')) { btn.setAttribute('data-ra-heading', '1'); continue; }
      var h = document.createElement('h3');
      h.style.display = 'contents';
      h.setAttribute('data-ra-cookie-heading', '1');
      btn.parentNode.insertBefore(h, btn);
      h.appendChild(btn);
      btn.setAttribute('data-ra-heading', '1');
    }
  }

  // AODA 1217163 (1.3.2): a collapsed category description is only visually hidden (max-height:0 /
  // opacity:0), which does NOT remove it from the accessibility tree — and its container has
  // tabindex="0" with a focusable "Learn more" link inside. So collapsed descriptions were reachable
  // by keyboard and readable by NVDA. Mark each description `inert` while its category is collapsed
  // (inert removes it from focus order AND the a11y tree) and clear it when expanded.
  function syncCookiePrefsInert() {
    var labels = document.querySelectorAll('.hs-category-label');
    for (var i = 0; i < labels.length; i++) {
      var btn = labels[i];
      var desc = document.getElementById(btn.getAttribute('aria-controls') || '');
      if (!desc) continue;
      if (btn.getAttribute('aria-expanded') === 'true') desc.removeAttribute('inert');
      else desc.setAttribute('inert', '');
    }
  }

  function applyCookiePrefsA11y() {
    if (!document.getElementById('hs-categories-container')) return;
    markCookiePrefsHeadings();
    syncCookiePrefsInert();
    // Re-sync inert whenever a category's aria-expanded flips (attribute we don't write → no loop).
    var container = document.getElementById('hs-categories-container');
    if (container && !container.getAttribute('data-ra-expand-obs')) {
      container.setAttribute('data-ra-expand-obs', '1');
      new MutationObserver(syncCookiePrefsInert).observe(container, {
        subtree: true, attributes: true, attributeFilter: ['aria-expanded']
      });
    }
  }

  function watchForCookiePrefsModal() {
    applyCookiePrefsA11y();
    // Watch childList (never attributes we write) → no observer loop; guards make it idempotent.
    var obs = new MutationObserver(applyCookiePrefsA11y);
    obs.observe(document.body, { childList: true, subtree: true });
  }

  // AODA 1217166 (2.4.3): a genuine cookie CLOSE control (the modal "X", Accept, Decline, Save
  // settings, Accept All) should hand focus back to the trigger. Delegated so it catches HubSpot's
  // dynamically-injected buttons. Must exclude controls that keep a surface open — "Cookie settings"
  // (opens the modal) and the category toggles — otherwise focus-return would fire during the
  // banner→modal transition and consume the stored trigger.
  document.addEventListener('click', function (e) {
    if (!e.target.closest) return;
    var byId = e.target.closest('#hs-modal-close-button, .hs-close-button, #hs-eu-confirmation-button, #hs-eu-decline-button');
    var textBtn = e.target.closest('#hs-modal button, #hs-eu-cookie-confirmation button');
    var isClose = byId || (textBtn && /^(accept|decline|reject|save settings|accept all)\b/i.test(textBtn.textContent.trim()));
    if (!isClose) return;
    returnCookieFocus();
  });

  document.addEventListener("DOMContentLoaded", function () {
    waitForCookieModal();
    watchForCookiePrefsModal();
  });
